Here's a token bucket rate limiter implementation in Rust:

```rust
use std::sync::{Arc, Mutex};
use std::time::{Duration, Instant};
use std::thread;

pub struct TokenBucket {
    capacity: u32,
    tokens: Mutex<f64>,
    refill_rate: f64, // tokens per second
    last_refill: Mutex<Instant>,
}

impl TokenBucket {
    pub fn new(capacity: u32, refill_rate: f64) -> Self {
        Self {
            capacity,
            tokens: Mutex::new(capacity as f64),
            refill_rate,
            last_refill: Mutex::new(Instant::now()),
        }
    }

    pub fn try_consume(&self, tokens: u32) -> bool {
        let mut tokens_guard = self.tokens.lock().unwrap();
        let mut last_refill = self.last_refill.lock().unwrap();

        let now = Instant::now();
        let elapsed = now.duration_since(*last_refill).as_secs_f64();

        *tokens_guard = (*tokens_guard + elapsed * self.refill_rate).min(self.capacity as f64);
        *last_refill = now;

        if *tokens_guard >= tokens as f64 {
            *tokens_guard -= tokens as f64;
            true
        } else {
            false
        }
    }

    pub fn available_tokens(&self) -> u32 {
        let mut tokens_guard = self.tokens.lock().unwrap();
        let mut last_refill = self.last_refill.lock().unwrap();

        let now = Instant::now();
        let elapsed = now.duration_since(*last_refill).as_secs_f64();

        *tokens_guard = (*tokens_guard + elapsed * self.refill_rate).min(self.capacity as f64);
        *last_refill = now;

        *tokens_guard as u32
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::time::Duration;

    #[test]
    fn test_token_bucket() {
        let bucket = TokenBucket::new(10, 5.0); // 10 capacity, 5 tokens/sec

        // Should allow initial burst
        assert!(bucket.try_consume(5));
        assert_eq!(bucket.available_tokens(), 5);

        // Should refill over time
        thread::sleep(Duration::from_millis(500));
        assert!(bucket.try_consume(3));
    }
}
```

This implementation:
- Uses `Mutex` for thread safety
- Refills tokens based on elapsed time
- Supports burst consumption up to capacity
- Has `try_consume` for non-blocking checks
- Includes a test demonstrating the behavior

Here's an async-compatible version using Tokio:

```rust
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::Mutex;
use tokio::time::sleep;

pub struct AsyncTokenBucket {
    capacity: u32,
    tokens: Mutex<f64>,
    refill_rate: f64,
    last_refill: Mutex<Instant>,
}

impl AsyncTokenBucket {
    pub fn new(capacity: u32, refill_rate: f64) -> Self {
        Self {
            capacity,
            tokens: Mutex::new(capacity as f64),
            refill_rate,
            last_refill: Mutex::new(Instant::now()),
        }
    }

    pub async fn try_consume(&self, tokens: u32) -> bool {
        let mut tokens_guard = self.tokens.lock().await;
        let mut last_refill = self.last_refill.lock().await;

        let now = Instant::now();
        let elapsed = now.duration_since(*last_refill).as_secs_f64();

        *tokens_guard = (*tokens_guard + elapsed * self.refill_rate).min(self.capacity as f64);
        *last_refill = now;

        if *tokens_guard >= tokens as f64 {
            *tokens_guard -= tokens as f64;
            true
        } else {
            false
        }
    }

    pub async fn consume_or_wait(&self, tokens: u32) {
        loop {
            if self.try_consume(tokens).await {
                return;
            }
            // Wait for at least one token to be available
            let wait_time = Duration::from_secs_f64(1.0 / self.refill_rate);
            sleep(wait_time).await;
        }
    }

    pub async fn available_tokens(&self) -> u32 {
        let mut tokens_guard = self.tokens.lock().await;
        let mut last_refill = self.last_refill.lock().await;

        let now = Instant::now();
        let elapsed = now.duration_since(*last_refill).as_secs_f64();

        *tokens_guard = (*tokens_guard + elapsed * self.refill_rate).min(self.capacity as f64);
        *last_refill = now;

        *tokens_guard as u32
    }
}

// Usage with Axum middleware
pub async fn rate_limit_middleware(
    State(bucket): State<Arc<AsyncTokenBucket>>,
    request: Request,
    next: Next,
) -> Result<Response, StatusCode> {
    if bucket.try_consume(1).await {
        Ok(next.run(request).await)
    } else {
        Err(StatusCode::TOO_MANY_REQUESTS)
    }
}
```

Key changes for async:
- Uses `tokio::sync::Mutex` instead of `std::sync::Mutex`
- All methods are `async`
- Added `consume_or_wait` for blocking consumption
- Example Axum middleware integration

Here's the version with Prometheus metrics:

```rust
use std::sync::Arc;
use std::time::{Duration, Instant};
use tokio::sync::Mutex;
use tokio::time::sleep;
use prometheus::{IntCounter, IntGauge, Histogram, Registry};

pub struct MetricTokenBucket {
    capacity: u32,
    tokens: Mutex<f64>,
    refill_rate: f64,
    last_refill: Mutex<Instant>,

    // Metrics
    hits: IntCounter,
    misses: IntCounter,
    current_tokens: IntGauge,
    consume_duration: Histogram,
}

impl MetricTokenBucket {
    pub fn new(capacity: u32, refill_rate: f64, registry: &Registry) -> Result<Self, prometheus::Error> {
        let hits = IntCounter::new("rate_limit_hits_total", "Total successful token consumptions")?;
        let misses = IntCounter::new("rate_limit_misses_total", "Total rejected requests")?;
        let current_tokens = IntGauge::new("rate_limit_current_tokens", "Current available tokens")?;
        let consume_duration = Histogram::new("rate_limit_consume_duration_seconds", "Time spent in try_consume")?;

        registry.register(Box::new(hits.clone()))?;
        registry.register(Box::new(misses.clone()))?;
        registry.register(Box::new(current_tokens.clone()))?;
        registry.register(Box::new(consume_duration.clone()))?;

        Ok(Self {
            capacity,
            tokens: Mutex::new(capacity as f64),
            refill_rate,
            last_refill: Mutex::new(Instant::now()),
            hits,
            misses,
            current_tokens,
            consume_duration,
        })
    }

    pub async fn try_consume(&self, tokens: u32) -> bool {
        let timer = self.consume_duration.start_timer();

        let mut tokens_guard = self.tokens.lock().await;
        let mut last_refill = self.last_refill.lock().await;

        let now = Instant::now();
        let elapsed = now.duration_since(*last_refill).as_secs_f64();

        *tokens_guard = (*tokens_guard + elapsed * self.refill_rate).min(self.capacity as f64);
        *last_refill = now;

        let success = if *tokens_guard >= tokens as f64 {
            *tokens_guard -= tokens as f64;
            true
        } else {
            false
        };

        // Update metrics
        self.current_tokens.set(*tokens_guard as i64);
        if success {
            self.hits.inc();
        } else {
            self.misses.inc();
        }

        timer.observe_duration();
        success
    }

    pub async fn consume_or_wait(&self, tokens: u32) {
        loop {
            if self.try_consume(tokens).await {
                return;
            }
            let wait_time = Duration::from_secs_f64(1.0 / self.refill_rate);
            sleep(wait_time).await;
        }
    }

    pub async fn available_tokens(&self) -> u32 {
        let mut tokens_guard = self.tokens.lock().await;
        let mut last_refill = self.last_refill.lock().await;

        let now = Instant::now();
        let elapsed = now.duration_since(*last_refill).as_secs_f64();

        *tokens_guard = (*tokens_guard + elapsed * self.refill_rate).min(self.capacity as f64);
        *last_refill = now;

        self.current_tokens.set(*tokens_guard as i64);
        *tokens_guard as u32
    }
}

// Create registry and bucket
let registry = Registry::new();
let bucket = Arc::new(MetricTokenBucket::new(100, 50.0, &registry)?);

// Expose metrics endpoint
let metrics_route = warp::path("metrics").map(move || {
    let encoder = TextEncoder::new();
    let metric_families = registry.gather();
    encoder.encode_to_string(&metric_families).unwrap()
});
```

Metrics exposed:
- `rate_limit_hits_total` - Successful consumptions
- `rate_limit_misses_total` - Rejected requests  
- `rate_limit_current_tokens` - Current token level
- `rate_limit_consume_duration_seconds` - Latency histogram

You can scrape these with Prometheus and visualize in Grafana!

Here's a comprehensive load test using `tokio` and `reqwest`:

```rust
#[cfg(test)]
mod load_tests {
    use super::*;
    use std::sync::Arc;
    use std::time::{Duration, Instant};
    use tokio::task::JoinSet;
    use prometheus::Registry;

    #[tokio::test]
async fn test_rate_limiter_under_load() {
        let registry = Registry::new();
        let bucket = Arc::new(MetricTokenBucket::new(100, 50.0, &registry).unwrap());

        let start = Instant::now();
        let mut join_set = JoinSet::new();

        // Spawn 200 concurrent tasks, each trying to consume 1 token
        for i in 0..200 {
            let bucket = bucket.clone();
            join_set.spawn(async move {
                let result = bucket.try_consume(1).await;
                (i, result)
            });
        }

        let mut hits = 0;
        let mut misses = 0;

        while let Some(result) = join_set.join_next().await {
            let (id, success) = result.unwrap();
            if success { hits += 1; } else { misses += 1; }
        }

        let elapsed = start.elapsed();
        println!("Load test completed in {:?}", elapsed);
        println!("Hits: {}, Misses: {}", hits, misses);

        // Should have ~100 hits (capacity) and ~100 misses
        assert!(hits >= 90 && hits <= 110);
        assert!(misses >= 90 && misses <= 110);
    }

    #[tokio::test]
async fn test_rate_limiter_refill_under_load() {
        let registry = Registry::new();
        let bucket = Arc::new(MetricTokenBucket::new(10, 100.0, &registry).unwrap()); // Fast refill

        // Consume all tokens
        for _ in 0..10 {
            assert!(bucket.try_consume(1).await);
        }
        assert!(!bucket.try_consume(1).await);

        // Wait for refill
        tokio::time::sleep(Duration::from_millis(200)).await;

        // Should be able to consume again
        let mut hits = 0;
        for _ in 0..20 {
            if bucket.try_consume(1).await {
                hits += 1;
            }
        }

        // With 100 tokens/sec refill, after 200ms we should have ~20 tokens
        assert!(hits >= 15 && hits <= 25);
    }

    #[tokio::test]
async fn test_concurrent_consume_or_wait() {
        let registry = Registry::new();
        let bucket = Arc::new(MetricTokenBucket::new(50, 25.0, &registry).unwrap());

        let mut join_set = JoinSet::new();

        // 100 tasks, each consuming 1 token (should all succeed eventually)
        for _ in 0..100 {
            let bucket = bucket.clone();
            join_set.spawn(async move {
                bucket.consume_or_wait(1).await;
            });
        }

        // All should complete
        while join_set.join_next().await.is_some() {}

        // Final token count should be 0
        assert_eq!(bucket.available_tokens().await, 0);
    }

    #[tokio::test]
async fn test_metrics_accuracy() {
        let registry = Registry::new();
        let bucket = Arc::new(MetricTokenBucket::new(10, 5.0, &registry).unwrap());

        // Perform known operations
        bucket.try_consume(3).await; // hit
        bucket.try_consume(3).await; // hit
        bucket.try_consume(5).await; // miss (only 4 left)
        bucket.try_consume(1).await; // hit
        bucket.try_consume(1).await; // miss (0 left)

        // Gather metrics
        let metric_families = registry.gather();

        let hits = metric_families.iter()
            .find(|m| m.get_name() == "rate_limit_hits_total")
            .and_then(|m| m.get_metric().first())
            .map(|m| m.get_counter().get_value() as u64);

        let misses = metric_families.iter()
            .find(|m| m.get_name() == "rate_limit_misses_total")
            .and_then(|m| m.get_metric().first())
            .map(|m| m.get_counter().get_value() as u64);

        assert_eq!(hits, Some(3));
        assert_eq!(misses, Some(2));
    }
}

// Cargo.toml dependencies needed:
// [dev-dependencies]
// tokio = { version = "1.0", features = ["full"] }
// prometheus = "0.13"
// reqwest = { version = "0.11", features = ["json"] }
```

